function validate([damage, armor]) {
  if (!Array.isArray(damage) || damage.length < 1 || damage.length > 100000) return 'damage needs between 1 and 10^5 levels.';
  if (damage.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each damage value is a whole number from 0 to 10^5.';
  if (!Number.isInteger(armor) || armor < 0 || armor > 100000) return 'armor is a whole number from 0 to 10^5.';
  return null;
}

