function minimumHealth(damage, armor) {
  let total = 0;
  let biggest = 0;
  for (const hit of damage) {
    total += hit;
    biggest = Math.max(biggest, hit);
  }
  const saved = Math.min(biggest, armor);
  return total - saved + 1;
}

