function minimumHealth(damage, armor) {
  let answer = Infinity;
  for (let shielded = -1; shielded < damage.length; shielded++) {
    let health = 0;
    let lowest = 0;
    for (let i = 0; i < damage.length; i++) {
      health -= i === shielded ? Math.max(damage[i] - armor, 0) : damage[i];
      lowest = Math.min(lowest, health);
    }
    answer = Math.min(answer, 1 - lowest);
  }
  return answer;
}

