function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const mode = rand();
  if (size === 'large') {
    const n = pick(1500, 2000);
    const top = mode < 0.5 ? 100000 : pick(1, 1000);
    const damage = Array.from({ length: n }, () => (rand() < 0.1 ? 0 : pick(0, top)));
    const armor = rand() < 0.5 ? 100000 : pick(0, top);
    return [damage, armor];
  }
  const n = pick(1, 6);
  const top = mode < 0.15 ? 100000 : 12;
  const damage = Array.from({ length: n }, () => (rand() < 0.15 ? 0 : pick(0, top)));
  const choice = rand();
  const armor = choice < 0.2 ? 0 : choice < 0.3 ? 100000 : pick(0, top);
  return [damage, armor];
}
